 function updateHud(){timerEl.textContent=Math.ceil(time);scoreEl.textContent=score;joyFill.style.width=joy+'%';joyText.textContent=Math.round(joy)+'%';joyFill.style.background=joy<30?'linear-gradient(90deg,#fb8780,#f6bd74)':'linear-gradient(90deg,#ffb36b,#ffe379,#80d584)'}
 function start(){setup();running=true;ended=false;last=performance.now();overlay.classList.add('hidden');if(!audioCtx&&sound){try{audioCtx=new(window.AudioContext||window.webkitAudioContext)()}catch{}}requestAnimationFrame(loop)}
 function finish(win){if(ended)return;ended=true;running=false;document.getElementById('hero').textContent=win?'🏆🐑':'🥺🐑';document.getElementById('title').textContent=win?'The happiest flock!':'The flock needs a cuddle';document.getElementById('message').textContent=win?'You kept your sheep smiling for a whole minute. What a lovely meadow!':'Their joy ran out this time, but the clovers are still growing. Give it another go!';document.getElementById('instructions').style.display='none';document.querySelector('.resultline')?.remove();const p=document.createElement('p');p.className='resultline';p.textContent='Final joy '+Math.round(joy)+'%   ·   '+score+' happy moments';document.getElementById('message').after(p);startBtn.textContent='Play again';overlay.classList.remove('hidden')}
-function loop(now){if(!running)return;const dt=Math.min(.05,(now-last)/1000);last=now;gameElapsed+=dt;time-=dt;spawn+=dt;joy-=dt*(.24+sheep.length*.017);sheep.forEach(s=>{s.happy=Math.max(0,s.happy-dt*.24);s.x+=s.vx*dt;s.y+=s.vy*dt;s.phase+=dt*3;s.turn-=dt;if(s.turn<0){s.vx=rand(-23,23);s.vy=rand(-16,16);s.turn=rand(1,3)}if(s.x<42||s.x>W-42)s.vx*=-1;if(s.y<66||s.y>H-42)s.vy*=-1;s.x=clamp(s.x,42,W-42);s.y=clamp(s.y,66,H-42);s.pet=Math.max(0,s.pet-dt)});particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);if(spawn>8&&clovers.length<4){addClover();spawn=0}if(toastClock>0){toastClock-=dt;if(toastClock<=0)toast.classList.remove('show')}if(time<=0){time=0;updateHud();finish(true);return}if(joy<=0){joy=0;updateHud();finish(false);return}updateHud();draw();requestAnimationFrame(loop)}
+function loop(now){if(!running)return;const dt=Math.min(.05,(now-last)/1000);last=now;gameElapsed+=dt;time-=dt;spawn+=dt;joy-=dt*(1+sheep.length*.02);sheep.forEach(s=>{s.happy=Math.max(0,s.happy-dt*.24);s.x+=s.vx*dt;s.y+=s.vy*dt;s.phase+=dt*3;s.turn-=dt;if(s.turn<0){s.vx=rand(-23,23);s.vy=rand(-16,16);s.turn=rand(1,3)}if(s.x<42||s.x>W-42)s.vx*=-1;if(s.y<66||s.y>H-42)s.vy*=-1;s.x=clamp(s.x,42,W-42);s.y=clamp(s.y,66,H-42);s.pet=Math.max(0,s.pet-dt)});particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);if(spawn>8&&clovers.length<4){addClover();spawn=0}if(toastClock>0){toastClock-=dt;if(toastClock<=0)toast.classList.remove('show')}if(time<=0){time=0;updateHud();finish(true);return}if(joy<=0){joy=0;updateHud();finish(false);return}updateHud();draw();requestAnimationFrame(loop)}
 function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
 function draw(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#bfe9ab');sky.addColorStop(1,'#a5d990');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // soft rolling hills
 ctx.fillStyle='#a1d58e';ctx.beginPath();ctx.moveTo(0,H*.35);ctx.bezierCurveTo(W*.24,H*.18,W*.38,H*.42,W*.63,H*.27);ctx.bezierCurveTo(W*.8,H*.17,W*.89,H*.28,W,H*.2);ctx.lineTo(W,0);ctx.lineTo(0,0);ctx.fill();

